INSERT INTO `jobs` VALUES (10001,'软件开发-后台开发方向','企业发展事业群','深圳总部','软件开发','后台开发','技术','应届实习','实习生','应届实习','你是腾讯产品「背后」的英雄，打造出更稳定安全、高效可靠的后台支撑体系，守护海量用户的笑容！','负责实现和优化公司的产品功能，以及构建和维护关键服务与基础设施。','负责实现和优化公司的产品功能，以及构建和维护关键服务与基础设施。','【必备要求】\n扎实的编程能力\n熟练掌握 C/C++/Java/Go 等其中一门开发语言\n熟悉 TCP/UDP 网络协议及相关编程、进程间通讯编程\n具备算法、操作系统、软件工程、设计模式、数据结构、数据库系统、网络安全等专业软件知识\n\n【了解项】\n了解 Python、Shell、Perl 等脚本语言\n了解 MySQL 及 SQL 编程\n了解 NoSQL、Key-Value 存储原理\n\n【加分项】\n了解分布式系统设计与开发、负载均衡、系统容灾、高可用系统等知识\n对云原生相关技术有所了解','[\"深入理解业务需求和产品设计，高效地实现并优化产品功能\", \"持续优化架构，提升关键服务和基础设施的稳定性与可用性\", \"通过引入新的工具和流程，提升团队的开发效率和代码质量\", \"通过与产品和前端工程师的紧密合作，共同推进产品的迭代与优化\", \"对线上问题进行快速定位并解决，对服务性能进行监控与优化\", \"参与新技术的研究和探索，为团队的技术进步和产品创新提供支持\"]','[\"扎实的编程能力\", \"熟练掌握 C/C++/Java/Go 等其中一门开发语言\", \"熟悉 TCP/UDP 网络协议及相关编程、进程间通讯编程\", \"具备算法、操作系统、软件工程、设计模式、数据结构、数据库系统、网络安全等专业软件知识\"]','[\"了解 Python、Shell、Perl 等脚本语言\", \"了解 MySQL 及 SQL 编程\", \"了解 NoSQL、Key-Value 存储原理\"]','[\"了解分布式系统设计与开发、负载均衡、系统容灾、高可用系统等知识\", \"对云原生相关技术有所了解\"]','null','[\"C/C++\", \"Java\", \"Go\", \"TCP/UDP\", \"MySQL\", \"NoSQL\", \"分布式系统\", \"云原生\", \"高可用\"]','[\"C/C++\", \"Java\", \"Go\", \"TCP/UDP\", \"MySQL\", \"NoSQL\", \"分布式系统\", \"云原生\", \"高可用\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}, {\"code\": \"S1\", \"name\": \"职能系统－职能线\"}, {\"code\": \"S2\", \"name\": \"职能系统－财经线\"}]','[\"深圳总部\", \"北京\", \"上海\", \"广州\", \"成都\", \"武汉\", \"杭州\"]','[\"上海\", \"远程面试\"]',NULL,'open','manual_curated','tencent-backend-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-backend-intern-2026-001\", \"title\": \"软件开发-后台开发方向\", \"slogan\": \"你是腾讯产品「背后」的英雄，打造出更稳定安全、高效可靠的后台支撑体系，守护海量用户的笑容！\", \"status\": \"open\", \"category\": \"后台开发\", \"job_type\": \"技术\", \"direction\": \"软件开发\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"深圳总部\", \"北京\", \"上海\", \"广州\", \"成都\", \"武汉\", \"杭州\"], \"job_type\": \"技术\", \"direction\": \"软件开发\", \"job_category\": \"后台开发\", \"business_groups\": [\"CDG\", \"CSIG\", \"IEG\", \"PCG\", \"TEG\", \"WXG\", \"S1\", \"S2\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"C/C++\", \"Java\", \"Go\", \"TCP/UDP\", \"MySQL\", \"NoSQL\", \"分布式系统\", \"云原生\", \"高可用\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"深圳总部\", \"北京\", \"上海\", \"广州\", \"成都\", \"武汉\", \"杭州\"], \"description\": {\"summary\": \"负责实现和优化公司的产品功能，以及构建和维护关键服务与基础设施。\", \"responsibilities\": [\"深入理解业务需求和产品设计，高效地实现并优化产品功能\", \"持续优化架构，提升关键服务和基础设施的稳定性与可用性\", \"通过引入新的工具和流程，提升团队的开发效率和代码质量\", \"通过与产品和前端工程师的紧密合作，共同推进产品的迭代与优化\", \"对线上问题进行快速定位并解决，对服务性能进行监控与优化\", \"参与新技术的研究和探索，为团队的技术进步和产品创新提供支持\"]}, \"requirements\": {\"must_have\": [\"扎实的编程能力\", \"熟练掌握 C/C++/Java/Go 等其中一门开发语言\", \"熟悉 TCP/UDP 网络协议及相关编程、进程间通讯编程\", \"具备算法、操作系统、软件工程、设计模式、数据结构、数据库系统、网络安全等专业软件知识\"], \"bonus_points\": [\"了解分布式系统设计与开发、负载均衡、系统容灾、高可用系统等知识\", \"对云原生相关技术有所了解\"], \"nice_to_have\": [\"了解 Python、Shell、Perl 等脚本语言\", \"了解 MySQL 及 SQL 编程\", \"了解 NoSQL、Key-Value 存储原理\"]}, \"organizations\": [{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}, {\"code\": \"S1\", \"name\": \"职能系统－职能线\"}, {\"code\": \"S2\", \"name\": \"职能系统－财经线\"}], \"interview_locations\": [\"上海\", \"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10002,'算法-多模态方向','企业发展事业群','深圳总部','算法','多模态','技术','应届实习','实习生','应届实习','对一个研究者来说，丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，而你正是其中一员！','负责多模态处理算法和模型的研究与开发，覆盖图像、视频、3D生成、声学信号理解与生成、多模态信息与文本信息对齐和整合等方向。','负责多模态处理算法和模型的研究与开发，覆盖图像、视频、3D生成、声学信号理解与生成、多模态信息与文本信息对齐和整合等方向。','【必备要求】\n包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士\n熟练掌握计算机视觉和图像处理相关的基本算法及应用\n熟悉 Caffe、TensorFlow、PyTorch 等至少一个深度学习框架\n较强的工程实现能力\n熟练掌握 C/C++ 编程\n熟悉 Shell、Python、Matlab 至少一种编程语言\n\n【了解项】\n熟悉多模态、NLP、CV 等方向的前沿技术\n具备图像、视频、3D生成、声学信号、多模态对齐等相关项目经验\n\n【加分项】\n在 CVPR、ICCV、ECCV、ACL、NeurIPS、ICLR 等学术会议或期刊以第一作者发表过文章\n有丰富项目经验','[\"研究和开发多模态处理算法和模型，包括图像、视频、3D生成、声学信号的理解与生成、多模态信息和文本信息的对齐与整合\", \"设计和优化现有算法，提高性能和准确性，确保高质量的用户体验\", \"深入调研和关注多模态、NLP、CV 等方向的前沿技术，及时将新技术应用到产品中\"]','[\"包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士\", \"熟练掌握计算机视觉和图像处理相关的基本算法及应用\", \"熟悉 Caffe、TensorFlow、PyTorch 等至少一个深度学习框架\", \"较强的工程实现能力\", \"熟练掌握 C/C++ 编程\", \"熟悉 Shell、Python、Matlab 至少一种编程语言\"]','[\"熟悉多模态、NLP、CV 等方向的前沿技术\", \"具备图像、视频、3D生成、声学信号、多模态对齐等相关项目经验\"]','[\"在 CVPR、ICCV、ECCV、ACL、NeurIPS、ICLR 等学术会议或期刊以第一作者发表过文章\", \"有丰富项目经验\"]','null','[\"多模态\", \"计算机视觉\", \"图像处理\", \"视频理解\", \"3D生成\", \"声学信号处理\", \"NLP\", \"CV\", \"C/C++\", \"Python\", \"Shell\", \"Matlab\", \"Caffe\", \"TensorFlow\", \"PyTorch\", \"深度学习\"]','[\"多模态\", \"计算机视觉\", \"图像处理\", \"视频理解\", \"3D生成\", \"声学信号处理\", \"NLP\", \"CV\", \"C/C++\", \"Python\", \"Shell\", \"Matlab\", \"Caffe\", \"TensorFlow\", \"PyTorch\", \"深度学习\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}]','[\"深圳总部\", \"北京\", \"上海\", \"广州\", \"成都\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-algorithm-multimodal-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-algorithm-multimodal-intern-2026-001\", \"title\": \"算法-多模态方向\", \"slogan\": \"对一个研究者来说，丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，而你正是其中一员！\", \"status\": \"open\", \"category\": \"多模态\", \"job_type\": \"技术\", \"direction\": \"算法\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"深圳总部\", \"北京\", \"上海\", \"广州\", \"成都\"], \"job_type\": \"技术\", \"direction\": \"算法\", \"job_category\": \"多模态\", \"business_groups\": [\"CDG\", \"CSIG\", \"IEG\", \"PCG\", \"TEG\", \"WXG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"多模态\", \"计算机视觉\", \"图像处理\", \"视频理解\", \"3D生成\", \"声学信号处理\", \"NLP\", \"CV\", \"C/C++\", \"Python\", \"Shell\", \"Matlab\", \"Caffe\", \"TensorFlow\", \"PyTorch\", \"深度学习\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"深圳总部\", \"北京\", \"上海\", \"广州\", \"成都\"], \"description\": {\"summary\": \"负责多模态处理算法和模型的研究与开发，覆盖图像、视频、3D生成、声学信号理解与生成、多模态信息与文本信息对齐和整合等方向。\", \"responsibilities\": [\"研究和开发多模态处理算法和模型，包括图像、视频、3D生成、声学信号的理解与生成、多模态信息和文本信息的对齐与整合\", \"设计和优化现有算法，提高性能和准确性，确保高质量的用户体验\", \"深入调研和关注多模态、NLP、CV 等方向的前沿技术，及时将新技术应用到产品中\"]}, \"requirements\": {\"must_have\": [\"包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士\", \"熟练掌握计算机视觉和图像处理相关的基本算法及应用\", \"熟悉 Caffe、TensorFlow、PyTorch 等至少一个深度学习框架\", \"较强的工程实现能力\", \"熟练掌握 C/C++ 编程\", \"熟悉 Shell、Python、Matlab 至少一种编程语言\"], \"bonus_points\": [\"在 CVPR、ICCV、ECCV、ACL、NeurIPS、ICLR 等学术会议或期刊以第一作者发表过文章\", \"有丰富项目经验\"], \"nice_to_have\": [\"熟悉多模态、NLP、CV 等方向的前沿技术\", \"具备图像、视频、3D生成、声学信号、多模态对齐等相关项目经验\"]}, \"organizations\": [{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10003,'算法-自然语言处理方向','企业发展事业群','深圳总部','算法','自然语言处理','技术','应届实习','实习生','应届实习','对一个研究者来说，丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，而你正是其中一员！','负责自然语言处理相关算法研发，覆盖语义分析、意图识别、人机对话、机器翻译、知识图谱、命名实体识别、自然语言生成等方向。','负责自然语言处理相关算法研发，覆盖语义分析、意图识别、人机对话、机器翻译、知识图谱、命名实体识别、自然语言生成等方向。','【必备要求】\n包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士\n熟练掌握 NLP 基础理论和算法\n在一个或多个 NLP 领域能够独立开展研发工作，如对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等\n熟悉至少一种编程语言，包括 Java、C/C++、C#、Python 等\n熟练使用一种或几种深度学习框架，如 TensorFlow、Caffe、MXNet、PyTorch 等\n\n【了解项】\n熟悉对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等一个或多个 NLP 方向\n具备深度学习学术或工程项目经验\n\n【加分项】\n在 ACL、EMNLP、SIGIR、NAACL、COLING、IJCAI、AAAI 等学术会议或期刊以第一作者发表过文章\n有深度学习学术或工程项目经验','[\"负责自然语言处理的算法研发，包括语义分析、意图识别、人机对话、语义挖掘、机器翻译、知识图谱、命名实体识别等\", \"负责对话系统，尤其是任务导向型对话系统的技术研究，包括自然语言理解、对话状态跟踪、对话策略学习、自然语言生成、encoder-decoder 模型等\", \"负责知识图谱相关关键技术研究，解决知识图谱和自然语言深层次表示、理解与计算问题\", \"负责 NLP 前沿问题的研究，结合未来实际应用场景，提供技术解决方案\"]','[\"包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士\", \"熟练掌握 NLP 基础理论和算法\", \"在一个或多个 NLP 领域能够独立开展研发工作，如对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等\", \"熟悉至少一种编程语言，包括 Java、C/C++、C#、Python 等\", \"熟练使用一种或几种深度学习框架，如 TensorFlow、Caffe、MXNet、PyTorch 等\"]','[\"熟悉对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等一个或多个 NLP 方向\", \"具备深度学习学术或工程项目经验\"]','[\"在 ACL、EMNLP、SIGIR、NAACL、COLING、IJCAI、AAAI 等学术会议或期刊以第一作者发表过文章\", \"有深度学习学术或工程项目经验\"]','null','[\"NLP\", \"自然语言处理\", \"语义分析\", \"意图识别\", \"人机对话\", \"任务导向型对话系统\", \"自然语言理解\", \"对话状态跟踪\", \"对话策略学习\", \"自然语言生成\", \"encoder-decoder\", \"机器翻译\", \"知识图谱\", \"命名实体识别\", \"文本分类\", \"情感分析\", \"Java\", \"C/C++\", \"C#\", \"Python\", \"TensorFlow\", \"Caffe\", \"MXNet\", \"PyTorch\", \"深度学习\"]','[\"NLP\", \"自然语言处理\", \"语义分析\", \"意图识别\", \"人机对话\", \"任务导向型对话系统\", \"自然语言理解\", \"对话状态跟踪\", \"对话策略学习\", \"自然语言生成\", \"encoder-decoder\", \"机器翻译\", \"知识图谱\", \"命名实体识别\", \"文本分类\", \"情感分析\", \"Java\", \"C/C++\", \"C#\", \"Python\", \"TensorFlow\", \"Caffe\", \"MXNet\", \"PyTorch\", \"深度学习\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}, {\"code\": \"S1\", \"name\": \"职能系统－职能线\"}]','[\"深圳总部\", \"北京\", \"上海\", \"广州\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-algorithm-nlp-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-algorithm-nlp-intern-2026-001\", \"title\": \"算法-自然语言处理方向\", \"slogan\": \"对一个研究者来说，丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，而你正是其中一员！\", \"status\": \"open\", \"category\": \"自然语言处理\", \"job_type\": \"技术\", \"direction\": \"算法\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"深圳总部\", \"北京\", \"上海\", \"广州\"], \"job_type\": \"技术\", \"direction\": \"算法\", \"job_category\": \"自然语言处理\", \"business_groups\": [\"CDG\", \"CSIG\", \"IEG\", \"PCG\", \"TEG\", \"WXG\", \"S1\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"NLP\", \"自然语言处理\", \"语义分析\", \"意图识别\", \"人机对话\", \"任务导向型对话系统\", \"自然语言理解\", \"对话状态跟踪\", \"对话策略学习\", \"自然语言生成\", \"encoder-decoder\", \"机器翻译\", \"知识图谱\", \"命名实体识别\", \"文本分类\", \"情感分析\", \"Java\", \"C/C++\", \"C#\", \"Python\", \"TensorFlow\", \"Caffe\", \"MXNet\", \"PyTorch\", \"深度学习\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"深圳总部\", \"北京\", \"上海\", \"广州\"], \"description\": {\"summary\": \"负责自然语言处理相关算法研发，覆盖语义分析、意图识别、人机对话、机器翻译、知识图谱、命名实体识别、自然语言生成等方向。\", \"responsibilities\": [\"负责自然语言处理的算法研发，包括语义分析、意图识别、人机对话、语义挖掘、机器翻译、知识图谱、命名实体识别等\", \"负责对话系统，尤其是任务导向型对话系统的技术研究，包括自然语言理解、对话状态跟踪、对话策略学习、自然语言生成、encoder-decoder 模型等\", \"负责知识图谱相关关键技术研究，解决知识图谱和自然语言深层次表示、理解与计算问题\", \"负责 NLP 前沿问题的研究，结合未来实际应用场景，提供技术解决方案\"]}, \"requirements\": {\"must_have\": [\"包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士\", \"熟练掌握 NLP 基础理论和算法\", \"在一个或多个 NLP 领域能够独立开展研发工作，如对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等\", \"熟悉至少一种编程语言，包括 Java、C/C++、C#、Python 等\", \"熟练使用一种或几种深度学习框架，如 TensorFlow、Caffe、MXNet、PyTorch 等\"], \"bonus_points\": [\"在 ACL、EMNLP、SIGIR、NAACL、COLING、IJCAI、AAAI 等学术会议或期刊以第一作者发表过文章\", \"有深度学习学术或工程项目经验\"], \"nice_to_have\": [\"熟悉对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等一个或多个 NLP 方向\", \"具备深度学习学术或工程项目经验\"]}, \"organizations\": [{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}, {\"code\": \"S1\", \"name\": \"职能系统－职能线\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10004,'技术研究-高性能计算方向','企业发展事业群','深圳总部','技术研究','高性能计算','技术','应届实习','实习生','应届实习','对一个研究者来说，丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，而你正是其中一员！','负责 GPU、网络、大模型工程框架等高性能计算方向的技术研究与工程优化，解决算力瓶颈、通信延迟、分布式系统扩展性等问题。','负责 GPU、网络、大模型工程框架等高性能计算方向的技术研究与工程优化，解决算力瓶颈、通信延迟、分布式系统扩展性等问题。','【必备要求】\n扎实的计算机体系结构基础\n熟悉并行计算、数据密集型系统设计\n良好的数学基础，包括线性代数、数值分析、算法复杂度优化\n\n【了解项】\n熟悉 GPU 集群调度、混合精度计算、模型量化等 GPU 加速技术\n熟悉低延迟、高吞吐分布式网络架构\n熟悉大模型训练框架与分布式训练策略\n\n【加分项】\n有 TensorRT、Triton Inference Server 等推理框架经验者优先\n深入理解 TCP/IP、RDMA 协议栈者优先\n熟悉 DPDK、SPDK 开发者优先\n有超算中心或云计算网络调优经验者优先\n熟悉 Transformer 架构及主流大模型训练流程','[\"针对业务需求，解决算力瓶颈、通信延迟、分布式系统扩展性等问题\", \"协同算法、硬件及运维团队，构建高效、稳定的计算基础设施\", \"研究 GPU 集群调度策略，优化资源利用率，探索混合精度计算、模型量化等 GPU 加速技术\", \"设计低延迟、高吞吐的分布式网络架构，如 InfiniBand、RoCE、DPU\", \"优化 MPI、NCCL 等通信库性能，解决大规模集群中的网络拥塞问题\", \"开发或优化大模型训练框架，如 PyTorch、TensorFlow、DeepSpeed、Megatron-LM\", \"设计分布式训练策略，包括模型并行、流水线并行、混合并行，提升千亿级参数模型训练效率\", \"研究训练加速技术，包括梯度压缩、显存优化、动态计算图调度\"]','[\"扎实的计算机体系结构基础\", \"熟悉并行计算、数据密集型系统设计\", \"良好的数学基础，包括线性代数、数值分析、算法复杂度优化\"]','[\"熟悉 GPU 集群调度、混合精度计算、模型量化等 GPU 加速技术\", \"熟悉低延迟、高吞吐分布式网络架构\", \"熟悉大模型训练框架与分布式训练策略\"]','[\"有 TensorRT、Triton Inference Server 等推理框架经验者优先\", \"深入理解 TCP/IP、RDMA 协议栈者优先\", \"熟悉 DPDK、SPDK 开发者优先\", \"有超算中心或云计算网络调优经验者优先\", \"熟悉 Transformer 架构及主流大模型训练流程\"]','null','[\"高性能计算\", \"GPU\", \"GPU集群调度\", \"并行计算\", \"数据密集型系统\", \"分布式系统\", \"计算机体系结构\", \"混合精度计算\", \"模型量化\", \"InfiniBand\", \"RoCE\", \"DPU\", \"MPI\", \"NCCL\", \"PyTorch\", \"TensorFlow\", \"DeepSpeed\", \"Megatron-LM\", \"模型并行\", \"流水线并行\", \"混合并行\", \"梯度压缩\", \"显存优化\", \"动态计算图调度\", \"TensorRT\", \"Triton Inference Server\", \"TCP/IP\", \"RDMA\", \"DPDK\", \"SPDK\", \"Transformer\", \"大模型训练\"]','[\"高性能计算\", \"GPU\", \"GPU集群调度\", \"并行计算\", \"数据密集型系统\", \"分布式系统\", \"计算机体系结构\", \"混合精度计算\", \"模型量化\", \"InfiniBand\", \"RoCE\", \"DPU\", \"MPI\", \"NCCL\", \"PyTorch\", \"TensorFlow\", \"DeepSpeed\", \"Megatron-LM\", \"模型并行\", \"流水线并行\", \"混合并行\", \"梯度压缩\", \"显存优化\", \"动态计算图调度\", \"TensorRT\", \"Triton Inference Server\", \"TCP/IP\", \"RDMA\", \"DPDK\", \"SPDK\", \"Transformer\", \"大模型训练\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}]','[\"深圳总部\", \"北京\", \"上海\", \"广州\", \"合肥\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-tech-research-hpc-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-tech-research-hpc-intern-2026-001\", \"title\": \"技术研究-高性能计算方向\", \"slogan\": \"对一个研究者来说，丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，而你正是其中一员！\", \"status\": \"open\", \"category\": \"高性能计算\", \"job_type\": \"技术\", \"direction\": \"技术研究\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"深圳总部\", \"北京\", \"上海\", \"广州\", \"合肥\"], \"job_type\": \"技术\", \"direction\": \"技术研究\", \"job_category\": \"高性能计算\", \"business_groups\": [\"CDG\", \"CSIG\", \"IEG\", \"TEG\", \"WXG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"高性能计算\", \"GPU\", \"GPU集群调度\", \"并行计算\", \"数据密集型系统\", \"分布式系统\", \"计算机体系结构\", \"混合精度计算\", \"模型量化\", \"InfiniBand\", \"RoCE\", \"DPU\", \"MPI\", \"NCCL\", \"PyTorch\", \"TensorFlow\", \"DeepSpeed\", \"Megatron-LM\", \"模型并行\", \"流水线并行\", \"混合并行\", \"梯度压缩\", \"显存优化\", \"动态计算图调度\", \"TensorRT\", \"Triton Inference Server\", \"TCP/IP\", \"RDMA\", \"DPDK\", \"SPDK\", \"Transformer\", \"大模型训练\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"深圳总部\", \"北京\", \"上海\", \"广州\", \"合肥\"], \"description\": {\"summary\": \"负责 GPU、网络、大模型工程框架等高性能计算方向的技术研究与工程优化，解决算力瓶颈、通信延迟、分布式系统扩展性等问题。\", \"responsibilities\": [\"针对业务需求，解决算力瓶颈、通信延迟、分布式系统扩展性等问题\", \"协同算法、硬件及运维团队，构建高效、稳定的计算基础设施\", \"研究 GPU 集群调度策略，优化资源利用率，探索混合精度计算、模型量化等 GPU 加速技术\", \"设计低延迟、高吞吐的分布式网络架构，如 InfiniBand、RoCE、DPU\", \"优化 MPI、NCCL 等通信库性能，解决大规模集群中的网络拥塞问题\", \"开发或优化大模型训练框架，如 PyTorch、TensorFlow、DeepSpeed、Megatron-LM\", \"设计分布式训练策略，包括模型并行、流水线并行、混合并行，提升千亿级参数模型训练效率\", \"研究训练加速技术，包括梯度压缩、显存优化、动态计算图调度\"]}, \"requirements\": {\"must_have\": [\"扎实的计算机体系结构基础\", \"熟悉并行计算、数据密集型系统设计\", \"良好的数学基础，包括线性代数、数值分析、算法复杂度优化\"], \"bonus_points\": [\"有 TensorRT、Triton Inference Server 等推理框架经验者优先\", \"深入理解 TCP/IP、RDMA 协议栈者优先\", \"熟悉 DPDK、SPDK 开发者优先\", \"有超算中心或云计算网络调优经验者优先\", \"熟悉 Transformer 架构及主流大模型训练流程\"], \"nice_to_have\": [\"熟悉 GPU 集群调度、混合精度计算、模型量化等 GPU 加速技术\", \"熟悉低延迟、高吞吐分布式网络架构\", \"熟悉大模型训练框架与分布式训练策略\"]}, \"organizations\": [{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10005,'解决方案-行业咨询方向','云与智慧产业事业群','深圳总部','解决方案','行业咨询','技术','应届实习','实习生','应届实习','你将在充满机遇与挑战的工作中，成为客户与技术产品间的桥梁，为产业发展提供多元价值。深耕产业，拥抱未来！','负责学习和理解技术、产品及应用场景，挖掘客户需求，结合腾讯平台能力提供行业解决方案，并参与售前咨询、项目交付、售后服务等环节。','负责学习和理解技术、产品及应用场景，挖掘客户需求，结合腾讯平台能力提供行业解决方案，并参与售前咨询、项目交付、售后服务等环节。','【必备要求】\n理工科专业\n具有出色的书面和口头沟通能力、人际沟通能力\n富有创造性、灵活性及自信心\n具备快速学习能力，能够快速获取、整理及分析信息\n逻辑性强，具有良好的商业意识和客户服务意识\n目标感强，自我驱动，以结果为导向\n能接受出差\n\n【了解项】\n熟悉云计算、大数据、人工智能等技术优先\n具备产品架构设计、售前咨询、项目交付、售后服务相关理解或实践经验\n具备企业数字化转型解决方案相关理解\n\n【加分项】\n同等条件下，有腾讯云从业资格认证者优先','[\"学习和理解技术、产品及应用场景，挖掘和引导客户需求，结合腾讯平台能力为客户提供解决方案\", \"深度参与产品架构设计、售前咨询、项目交付、售后服务其中一个或多个环节，保障解决方案落地，解决客户问题，助力客户成功\", \"学习解决方案的最佳实践，并通过实战经验积累，沉淀面向企业数字化转型的通用方案能力与优势\", \"保持市场洞察，感知行业动态，不断提升公司产品和解决方案的行业竞争力\"]','[\"理工科专业\", \"具有出色的书面和口头沟通能力、人际沟通能力\", \"富有创造性、灵活性及自信心\", \"具备快速学习能力，能够快速获取、整理及分析信息\", \"逻辑性强，具有良好的商业意识和客户服务意识\", \"目标感强，自我驱动，以结果为导向\", \"能接受出差\"]','[\"熟悉云计算、大数据、人工智能等技术优先\", \"具备产品架构设计、售前咨询、项目交付、售后服务相关理解或实践经验\", \"具备企业数字化转型解决方案相关理解\"]','[\"同等条件下，有腾讯云从业资格认证者优先\"]','null','[\"解决方案\", \"行业咨询\", \"云计算\", \"大数据\", \"人工智能\", \"售前咨询\", \"项目交付\", \"售后服务\", \"产品架构设计\", \"客户需求分析\", \"企业数字化转型\", \"市场洞察\", \"商业意识\", \"客户服务\", \"沟通表达\", \"信息整理分析\"]','[\"解决方案\", \"行业咨询\", \"云计算\", \"大数据\", \"人工智能\", \"售前咨询\", \"项目交付\", \"售后服务\", \"产品架构设计\", \"客户需求分析\", \"企业数字化转型\", \"市场洞察\", \"商业意识\", \"客户服务\", \"沟通表达\", \"信息整理分析\"]','[{\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}]','[\"深圳总部\", \"上海\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-solution-industry-consulting-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-solution-industry-consulting-intern-2026-001\", \"title\": \"解决方案-行业咨询方向\", \"slogan\": \"你将在充满机遇与挑战的工作中，成为客户与技术产品间的桥梁，为产业发展提供多元价值。深耕产业，拥抱未来！\", \"status\": \"open\", \"category\": \"行业咨询\", \"job_type\": \"技术\", \"direction\": \"解决方案\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"深圳总部\", \"上海\"], \"job_type\": \"技术\", \"direction\": \"解决方案\", \"job_category\": \"行业咨询\", \"business_groups\": [\"CSIG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"解决方案\", \"行业咨询\", \"云计算\", \"大数据\", \"人工智能\", \"售前咨询\", \"项目交付\", \"售后服务\", \"产品架构设计\", \"客户需求分析\", \"企业数字化转型\", \"市场洞察\", \"商业意识\", \"客户服务\", \"沟通表达\", \"信息整理分析\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"深圳总部\", \"上海\"], \"description\": {\"summary\": \"负责学习和理解技术、产品及应用场景，挖掘客户需求，结合腾讯平台能力提供行业解决方案，并参与售前咨询、项目交付、售后服务等环节。\", \"responsibilities\": [\"学习和理解技术、产品及应用场景，挖掘和引导客户需求，结合腾讯平台能力为客户提供解决方案\", \"深度参与产品架构设计、售前咨询、项目交付、售后服务其中一个或多个环节，保障解决方案落地，解决客户问题，助力客户成功\", \"学习解决方案的最佳实践，并通过实战经验积累，沉淀面向企业数字化转型的通用方案能力与优势\", \"保持市场洞察，感知行业动态，不断提升公司产品和解决方案的行业竞争力\"]}, \"requirements\": {\"must_have\": [\"理工科专业\", \"具有出色的书面和口头沟通能力、人际沟通能力\", \"富有创造性、灵活性及自信心\", \"具备快速学习能力，能够快速获取、整理及分析信息\", \"逻辑性强，具有良好的商业意识和客户服务意识\", \"目标感强，自我驱动，以结果为导向\", \"能接受出差\"], \"bonus_points\": [\"同等条件下，有腾讯云从业资格认证者优先\"], \"nice_to_have\": [\"熟悉云计算、大数据、人工智能等技术优先\", \"具备产品架构设计、售前咨询、项目交付、售后服务相关理解或实践经验\", \"具备企业数字化转型解决方案相关理解\"]}, \"organizations\": [{\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10006,'CSIG技术产品商务培训生','云与智慧产业事业群','青岛','技术产品商务','商务培训生','市场','应届实习','实习生','应届实习','一起投身到产业互联网浪潮中，以领先数字平台产品点亮智慧未来，遇见坚定稳步成长的自己！','加入 CSIG 技术产品商务培训生专项，面向国内外机构、企业组织和个人开发者，推广腾讯云核心产品和解决方案，挖掘潜在商机，参与完整客户业务合作过程。','加入 CSIG 技术产品商务培训生专项，面向国内外机构、企业组织和个人开发者，推广腾讯云核心产品和解决方案，挖掘潜在商机，参与完整客户业务合作过程。','【必备要求】\n具备良好的综合素质\n具备优秀的沟通和团队协作能力\n热爱挑战，能在复杂环境中探索解决路径\n愿意将给客户提供优秀的技术产品并达成商务目标作为个人职业发展方向\n积极拥抱云、大数据、人工智能等技术产品领域的变化\n具备快速学习能力及敏锐的市场洞察意识\n\n【了解项】\n计算机、信息技术、计算机交叉学科等相关专业背景优先\n商科专业背景，同时愿意快速学习技术产品知识\n具备云、大数据、人工智能等技术产品相关理解\n具备客户合作、商务拓展、市场洞察或解决方案相关实践经验\n\n【加分项】\n同等条件下，有腾讯云从业资格认证者优先\n曾担任过校园学生干部\n有校内活动组织、校外社会实践经验\n有大型互联网、IT 相关科技企业实习经历','[\"面向国内外各机构、企业组织和个人开发者，推广腾讯云的核心产品和解决方案\", \"综合直销和渠道分销等形式，挖掘潜在商机，助力团队共同实现业务目标\", \"代表公司深度参与完整的客户业务合作全过程\", \"完成深度的行业洞察、挖掘商机客群、制定和参与全方位的云与技术解决方案\", \"通过一线实践体验，实现个人快速提升和成长\"]','[\"具备良好的综合素质\", \"具备优秀的沟通和团队协作能力\", \"热爱挑战，能在复杂环境中探索解决路径\", \"愿意将给客户提供优秀的技术产品并达成商务目标作为个人职业发展方向\", \"积极拥抱云、大数据、人工智能等技术产品领域的变化\", \"具备快速学习能力及敏锐的市场洞察意识\"]','[\"计算机、信息技术、计算机交叉学科等相关专业背景优先\", \"商科专业背景，同时愿意快速学习技术产品知识\", \"具备云、大数据、人工智能等技术产品相关理解\", \"具备客户合作、商务拓展、市场洞察或解决方案相关实践经验\"]','[\"同等条件下，有腾讯云从业资格认证者优先\", \"曾担任过校园学生干部\", \"有校内活动组织、校外社会实践经验\", \"有大型互联网、IT 相关科技企业实习经历\"]','[\"从 2024 年开始，实习留用将成为获得 CSIG 技术产品商务培训生正式校招 offer 的唯一途径，也是必经之路\", \"期待投入至少 1.5 个月的实习时间\", \"实习期间由经验丰富导师 1v1 带教，并提供完善课程等培养资源\", \"实习期间有机会提前获得校招 Offer\"]','[\"技术产品商务\", \"商务拓展\", \"客户合作\", \"腾讯云\", \"云计算\", \"大数据\", \"人工智能\", \"产业互联网\", \"解决方案\", \"直销\", \"渠道分销\", \"商机挖掘\", \"行业洞察\", \"市场洞察\", \"客户需求分析\", \"沟通表达\", \"团队协作\", \"快速学习\", \"商务目标管理\"]','[\"技术产品商务\", \"商务拓展\", \"客户合作\", \"腾讯云\", \"云计算\", \"大数据\", \"人工智能\", \"产业互联网\", \"解决方案\", \"直销\", \"渠道分销\", \"商机挖掘\", \"行业洞察\", \"市场洞察\", \"客户需求分析\", \"沟通表达\", \"团队协作\", \"快速学习\", \"商务目标管理\"]','[{\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}]','[\"青岛\", \"深圳总部\", \"郑州\", \"北京\", \"上海\", \"广州\", \"成都\", \"杭州\", \"南京\", \"中国香港\", \"西安\", \"重庆\", \"厦门\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-csig-tech-product-business-trainee-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-csig-tech-product-business-trainee-intern-2026-001\", \"title\": \"CSIG技术产品商务培训生\", \"slogan\": \"一起投身到产业互联网浪潮中，以领先数字平台产品点亮智慧未来，遇见坚定稳步成长的自己！\", \"status\": \"open\", \"category\": \"商务培训生\", \"job_type\": \"市场\", \"direction\": \"技术产品商务\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"青岛\", \"深圳总部\", \"郑州\", \"北京\", \"上海\", \"广州\", \"成都\", \"杭州\", \"南京\", \"中国香港\", \"西安\", \"重庆\", \"厦门\"], \"job_type\": \"市场\", \"direction\": \"技术产品商务\", \"job_category\": \"商务培训生\", \"business_groups\": [\"CSIG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"技术产品商务\", \"商务拓展\", \"客户合作\", \"腾讯云\", \"云计算\", \"大数据\", \"人工智能\", \"产业互联网\", \"解决方案\", \"直销\", \"渠道分销\", \"商机挖掘\", \"行业洞察\", \"市场洞察\", \"客户需求分析\", \"沟通表达\", \"团队协作\", \"快速学习\", \"商务目标管理\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"青岛\", \"深圳总部\", \"郑州\", \"北京\", \"上海\", \"广州\", \"成都\", \"杭州\", \"南京\", \"中国香港\", \"西安\", \"重庆\", \"厦门\"], \"description\": {\"summary\": \"加入 CSIG 技术产品商务培训生专项，面向国内外机构、企业组织和个人开发者，推广腾讯云核心产品和解决方案，挖掘潜在商机，参与完整客户业务合作过程。\", \"responsibilities\": [\"面向国内外各机构、企业组织和个人开发者，推广腾讯云的核心产品和解决方案\", \"综合直销和渠道分销等形式，挖掘潜在商机，助力团队共同实现业务目标\", \"代表公司深度参与完整的客户业务合作全过程\", \"完成深度的行业洞察、挖掘商机客群、制定和参与全方位的云与技术解决方案\", \"通过一线实践体验，实现个人快速提升和成长\"]}, \"requirements\": {\"notes\": [\"从 2024 年开始，实习留用将成为获得 CSIG 技术产品商务培训生正式校招 offer 的唯一途径，也是必经之路\", \"期待投入至少 1.5 个月的实习时间\", \"实习期间由经验丰富导师 1v1 带教，并提供完善课程等培养资源\", \"实习期间有机会提前获得校招 Offer\"], \"must_have\": [\"具备良好的综合素质\", \"具备优秀的沟通和团队协作能力\", \"热爱挑战，能在复杂环境中探索解决路径\", \"愿意将给客户提供优秀的技术产品并达成商务目标作为个人职业发展方向\", \"积极拥抱云、大数据、人工智能等技术产品领域的变化\", \"具备快速学习能力及敏锐的市场洞察意识\"], \"bonus_points\": [\"同等条件下，有腾讯云从业资格认证者优先\", \"曾担任过校园学生干部\", \"有校内活动组织、校外社会实践经验\", \"有大型互联网、IT 相关科技企业实习经历\"], \"nice_to_have\": [\"计算机、信息技术、计算机交叉学科等相关专业背景优先\", \"商科专业背景，同时愿意快速学习技术产品知识\", \"具备云、大数据、人工智能等技术产品相关理解\", \"具备客户合作、商务拓展、市场洞察或解决方案相关实践经验\"]}, \"organizations\": [{\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10007,'项目管理','云与智慧产业事业群','深圳总部','项目管理','项目管理','产品','应届实习','实习生','应届实习','项目的达成需要你的推动与把控，你是项目推进的“大总管”，也是推动项目实现的多面手！','负责参与项目管理与统筹，协助团队推进需求落地、项目进度把控、风险预警、资源配置、流程优化和项目复盘，保障项目目标高效达成。','负责参与项目管理与统筹，协助团队推进需求落地、项目进度把控、风险预警、资源配置、流程优化和项目复盘，保障项目目标高效达成。','【必备要求】\n本科及以上学历\n了解项目开发过程、敏捷项目管理理论\n乐观开朗、善于沟通、擅长协作\n乐于用自己的能量感染他人\n拥有明确的职业规划，立足于项目管理岗位长期发展\n\n【了解项】\n具备项目管理、需求管理、资源协调、流程优化相关理解或实践经验\n熟悉敏捷项目管理、项目复盘、风险预警、成本分析等方法\n\n【加分项】\n有软件工程实习经历背景\n积极参与学生社团相关工作，担任过主要职务','[\"参与项目的管理与统筹，帮助团队合理理解、判断需求及方向，并进行内外资源部署，推动项目和需求落地，确保高效达成项目目标\", \"协助合理规划项目、相关团队及合作机制，把控项目进度，进行风险预警和资源配置，关注合作细节，推动解决问题\", \"协助项目的复盘和总结\", \"协助优化团队资源结构，进行需求、人力、成本分析\", \"负责制定和优化工作流程，运用工具将人工推进事务逐步标准化、流程化、高效化\"]','[\"本科及以上学历\", \"了解项目开发过程、敏捷项目管理理论\", \"乐观开朗、善于沟通、擅长协作\", \"乐于用自己的能量感染他人\", \"拥有明确的职业规划，立足于项目管理岗位长期发展\"]','[\"具备项目管理、需求管理、资源协调、流程优化相关理解或实践经验\", \"熟悉敏捷项目管理、项目复盘、风险预警、成本分析等方法\"]','[\"有软件工程实习经历背景\", \"积极参与学生社团相关工作，担任过主要职务\"]','null','[\"项目管理\", \"敏捷项目管理\", \"项目统筹\", \"需求管理\", \"资源协调\", \"进度把控\", \"风险预警\", \"资源配置\", \"流程优化\", \"项目复盘\", \"需求分析\", \"人力分析\", \"成本分析\", \"团队协作\", \"沟通表达\", \"问题推动\", \"标准化流程\"]','[\"项目管理\", \"敏捷项目管理\", \"项目统筹\", \"需求管理\", \"资源协调\", \"进度把控\", \"风险预警\", \"资源配置\", \"流程优化\", \"项目复盘\", \"需求分析\", \"人力分析\", \"成本分析\", \"团队协作\", \"沟通表达\", \"问题推动\", \"标准化流程\"]','[{\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}]','[\"深圳总部\", \"北京\", \"上海\", \"杭州\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-project-management-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-project-management-intern-2026-001\", \"title\": \"项目管理\", \"slogan\": \"项目的达成需要你的推动与把控，你是项目推进的“大总管”，也是推动项目实现的多面手！\", \"status\": \"open\", \"category\": \"项目管理\", \"job_type\": \"产品\", \"direction\": \"项目管理\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"深圳总部\", \"北京\", \"上海\", \"杭州\"], \"job_type\": \"产品\", \"direction\": \"项目管理\", \"job_category\": \"项目管理\", \"business_groups\": [\"CSIG\", \"IEG\", \"PCG\", \"TEG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"项目管理\", \"敏捷项目管理\", \"项目统筹\", \"需求管理\", \"资源协调\", \"进度把控\", \"风险预警\", \"资源配置\", \"流程优化\", \"项目复盘\", \"需求分析\", \"人力分析\", \"成本分析\", \"团队协作\", \"沟通表达\", \"问题推动\", \"标准化流程\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"深圳总部\", \"北京\", \"上海\", \"杭州\"], \"description\": {\"summary\": \"负责参与项目管理与统筹，协助团队推进需求落地、项目进度把控、风险预警、资源配置、流程优化和项目复盘，保障项目目标高效达成。\", \"responsibilities\": [\"参与项目的管理与统筹，帮助团队合理理解、判断需求及方向，并进行内外资源部署，推动项目和需求落地，确保高效达成项目目标\", \"协助合理规划项目、相关团队及合作机制，把控项目进度，进行风险预警和资源配置，关注合作细节，推动解决问题\", \"协助项目的复盘和总结\", \"协助优化团队资源结构，进行需求、人力、成本分析\", \"负责制定和优化工作流程，运用工具将人工推进事务逐步标准化、流程化、高效化\"]}, \"requirements\": {\"must_have\": [\"本科及以上学历\", \"了解项目开发过程、敏捷项目管理理论\", \"乐观开朗、善于沟通、擅长协作\", \"乐于用自己的能量感染他人\", \"拥有明确的职业规划，立足于项目管理岗位长期发展\"], \"bonus_points\": [\"有软件工程实习经历背景\", \"积极参与学生社团相关工作，担任过主要职务\"], \"nice_to_have\": [\"具备项目管理、需求管理、资源协调、流程优化相关理解或实践经验\", \"熟悉敏捷项目管理、项目复盘、风险预警、成本分析等方法\"]}, \"organizations\": [{\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10008,'行业运营','企业发展事业群','深圳总部','行业运营','行业运营','产品','应届实习','实习生','应届实习','你将作为连接市场与产品的桥梁，互联网的市场先锋、业务发展的“啄木鸟”。下一个伟大，由你开始！','负责行业市场扫描、行业机会识别、目标客户分析、商机跟踪、解决方案推动、客户价值提升、经营指标分析和业务风险预警，促进业务目标达成。','负责行业市场扫描、行业机会识别、目标客户分析、商机跟踪、解决方案推动、客户价值提升、经营指标分析和业务风险预警，促进业务目标达成。','【必备要求】\n本科及以上学历\n热爱互联网行业\n具备优秀的分析问题、解决问题、信息整合、数据挖掘、逻辑组织和观点提炼能力\n具备一定方案撰写能力\n具备一定 Excel 建模能力\n具备良好的沟通能力和团队合作精神\n\n【了解项】\n具备行业分析、市场洞察、商业模式分析相关理解或实践经验\n具备客户需求分析、解决方案推动、商机跟踪相关理解或实践经验\n具备经营分析、KPI 分析、数据报告输出或业务风险预警相关理解','[\"扫描行业市场，关注行业前沿动态，分析行业产业结构，识别行业新机会点\", \"洞察商业模式变化趋势，探索新的商业模式，通过市场深入分析了解产品在行业中的定位与价值，促进业务发展\", \"通过行业目标客户圈定和特点分析，发现和跟踪商机，深入分析客户需求和应用场景\", \"提供解决方案和产品能力并推动实施，使产品具备较好的商业交付能力\", \"协调公司内外部资源达成目标，内部衔接销售、产品，外部衔接客户、服务商等\", \"建立行业作战地图，跟踪客户转化和渗透提升，不断提升客户价值，积累大客户标杆，驱动整体目标达成\", \"协同业务团队战略规划，明确经营指标体系建设\", \"周期性进行经营指标分析及报告数据输出，分析 KPI 达成情况、机会和风险，建立业务风险预警机制\"]','[\"本科及以上学历\", \"热爱互联网行业\", \"具备优秀的分析问题、解决问题、信息整合、数据挖掘、逻辑组织和观点提炼能力\", \"具备一定方案撰写能力\", \"具备一定 Excel 建模能力\", \"具备良好的沟通能力和团队合作精神\"]','[\"具备行业分析、市场洞察、商业模式分析相关理解或实践经验\", \"具备客户需求分析、解决方案推动、商机跟踪相关理解或实践经验\", \"具备经营分析、KPI 分析、数据报告输出或业务风险预警相关理解\"]','[]','null','[\"行业运营\", \"市场分析\", \"行业分析\", \"行业洞察\", \"商业模式分析\", \"客户需求分析\", \"目标客户圈定\", \"商机挖掘\", \"商机跟踪\", \"解决方案\", \"产品能力推动\", \"商业交付\", \"资源协调\", \"客户转化\", \"客户渗透\", \"大客户标杆\", \"战略规划\", \"经营指标分析\", \"KPI分析\", \"数据报告\", \"业务风险预警\", \"信息整合\", \"数据挖掘\", \"方案撰写\", \"Excel建模\", \"沟通表达\", \"团队合作\"]','[\"行业运营\", \"市场分析\", \"行业分析\", \"行业洞察\", \"商业模式分析\", \"客户需求分析\", \"目标客户圈定\", \"商机挖掘\", \"商机跟踪\", \"解决方案\", \"产品能力推动\", \"商业交付\", \"资源协调\", \"客户转化\", \"客户渗透\", \"大客户标杆\", \"战略规划\", \"经营指标分析\", \"KPI分析\", \"数据报告\", \"业务风险预警\", \"信息整合\", \"数据挖掘\", \"方案撰写\", \"Excel建模\", \"沟通表达\", \"团队合作\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}]','[\"深圳总部\", \"北京\", \"上海\", \"广州\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-industry-operations-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-industry-operations-intern-2026-001\", \"title\": \"行业运营\", \"slogan\": \"你将作为连接市场与产品的桥梁，互联网的市场先锋、业务发展的“啄木鸟”。下一个伟大，由你开始！\", \"status\": \"open\", \"category\": \"行业运营\", \"job_type\": \"产品\", \"direction\": \"行业运营\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"深圳总部\", \"北京\", \"上海\", \"广州\"], \"job_type\": \"产品\", \"direction\": \"行业运营\", \"job_category\": \"行业运营\", \"business_groups\": [\"CDG\", \"CSIG\", \"IEG\", \"TEG\", \"WXG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"行业运营\", \"市场分析\", \"行业分析\", \"行业洞察\", \"商业模式分析\", \"客户需求分析\", \"目标客户圈定\", \"商机挖掘\", \"商机跟踪\", \"解决方案\", \"产品能力推动\", \"商业交付\", \"资源协调\", \"客户转化\", \"客户渗透\", \"大客户标杆\", \"战略规划\", \"经营指标分析\", \"KPI分析\", \"数据报告\", \"业务风险预警\", \"信息整合\", \"数据挖掘\", \"方案撰写\", \"Excel建模\", \"沟通表达\", \"团队合作\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"深圳总部\", \"北京\", \"上海\", \"广州\"], \"description\": {\"summary\": \"负责行业市场扫描、行业机会识别、目标客户分析、商机跟踪、解决方案推动、客户价值提升、经营指标分析和业务风险预警，促进业务目标达成。\", \"responsibilities\": [\"扫描行业市场，关注行业前沿动态，分析行业产业结构，识别行业新机会点\", \"洞察商业模式变化趋势，探索新的商业模式，通过市场深入分析了解产品在行业中的定位与价值，促进业务发展\", \"通过行业目标客户圈定和特点分析，发现和跟踪商机，深入分析客户需求和应用场景\", \"提供解决方案和产品能力并推动实施，使产品具备较好的商业交付能力\", \"协调公司内外部资源达成目标，内部衔接销售、产品，外部衔接客户、服务商等\", \"建立行业作战地图，跟踪客户转化和渗透提升，不断提升客户价值，积累大客户标杆，驱动整体目标达成\", \"协同业务团队战略规划，明确经营指标体系建设\", \"周期性进行经营指标分析及报告数据输出，分析 KPI 达成情况、机会和风险，建立业务风险预警机制\"]}, \"requirements\": {\"must_have\": [\"本科及以上学历\", \"热爱互联网行业\", \"具备优秀的分析问题、解决问题、信息整合、数据挖掘、逻辑组织和观点提炼能力\", \"具备一定方案撰写能力\", \"具备一定 Excel 建模能力\", \"具备良好的沟通能力和团队合作精神\"], \"bonus_points\": [], \"nice_to_have\": [\"具备行业分析、市场洞察、商业模式分析相关理解或实践经验\", \"具备客户需求分析、解决方案推动、商机跟踪相关理解或实践经验\", \"具备经营分析、KPI 分析、数据报告输出或业务风险预警相关理解\"]}, \"organizations\": [{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10009,'投资分析','企业发展事业群','北京','投资分析','投资分析','市场','应届实习','实习生','应届实习','You are a key player in connecting investment decisions with market dynamics. Here, you will apply your insight and judgment to provide objective and accurate investment advice.','负责互联网领域的行业与经济研究，参与投资项目挖掘、评估、尽职调查、交易执行、投后公司研究及团队知识库建设。','负责互联网领域的行业与经济研究，参与投资项目挖掘、评估、尽职调查、交易执行、投后公司研究及团队知识库建设。','【必备要求】\n对互联网、投资和腾讯有强烈兴趣、热情和商业敏感度\n具备高度诚信、投入度和自我驱动力\n顶尖院校本科或硕士学历，专业不限\n具备优秀的问题解决能力\n具备扎实的批判性思维能力\n中英文流利\n\n【了解项】\n具备互联网行业研究、经济研究、投资分析、商业分析相关理解或实践经验\n具备交易评估、尽职调查、投后研究或知识库建设相关理解\n\n【加分项】\n有顶尖咨询公司或投资银行实习经历者优先','[\"主导互联网领域相关行业和经济研究\", \"参与并支持投资项目的来源挖掘、评估、尽职调查和交易执行流程\", \"参与并支持投后公司研究活动\", \"增强并维护团队知识库\"]','[\"对互联网、投资和腾讯有强烈兴趣、热情和商业敏感度\", \"具备高度诚信、投入度和自我驱动力\", \"顶尖院校本科或硕士学历，专业不限\", \"具备优秀的问题解决能力\", \"具备扎实的批判性思维能力\", \"中英文流利\"]','[\"具备互联网行业研究、经济研究、投资分析、商业分析相关理解或实践经验\", \"具备交易评估、尽职调查、投后研究或知识库建设相关理解\"]','[\"有顶尖咨询公司或投资银行实习经历者优先\"]','[\"该岗位要求上传 PDF 版本简历\"]','[\"投资分析\", \"行业研究\", \"经济研究\", \"互联网行业\", \"商业分析\", \"投资判断\", \"Deal Sourcing\", \"项目评估\", \"尽职调查\", \"交易执行\", \"投后研究\", \"知识库建设\", \"问题解决\", \"批判性思维\", \"商业敏感度\", \"英文沟通\", \"中文沟通\", \"Consulting\", \"Investment Banking\"]','[\"投资分析\", \"行业研究\", \"经济研究\", \"互联网行业\", \"商业分析\", \"投资判断\", \"Deal Sourcing\", \"项目评估\", \"尽职调查\", \"交易执行\", \"投后研究\", \"知识库建设\", \"问题解决\", \"批判性思维\", \"商业敏感度\", \"英文沟通\", \"中文沟通\", \"Consulting\", \"Investment Banking\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}]','[\"北京\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-investment-analysis-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-investment-analysis-intern-2026-001\", \"title\": \"投资分析\", \"slogan\": \"You are a key player in connecting investment decisions with market dynamics. Here, you will apply your insight and judgment to provide objective and accurate investment advice.\", \"status\": \"open\", \"category\": \"投资分析\", \"job_type\": \"市场\", \"direction\": \"投资分析\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"北京\"], \"job_type\": \"市场\", \"direction\": \"投资分析\", \"job_category\": \"投资分析\", \"business_groups\": [\"CDG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"投资分析\", \"行业研究\", \"经济研究\", \"互联网行业\", \"商业分析\", \"投资判断\", \"Deal Sourcing\", \"项目评估\", \"尽职调查\", \"交易执行\", \"投后研究\", \"知识库建设\", \"问题解决\", \"批判性思维\", \"商业敏感度\", \"英文沟通\", \"中文沟通\", \"Consulting\", \"Investment Banking\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"北京\"], \"description\": {\"summary\": \"负责互联网领域的行业与经济研究，参与投资项目挖掘、评估、尽职调查、交易执行、投后公司研究及团队知识库建设。\", \"responsibilities\": [\"主导互联网领域相关行业和经济研究\", \"参与并支持投资项目的来源挖掘、评估、尽职调查和交易执行流程\", \"参与并支持投后公司研究活动\", \"增强并维护团队知识库\"]}, \"requirements\": {\"notes\": [\"该岗位要求上传 PDF 版本简历\"], \"must_have\": [\"对互联网、投资和腾讯有强烈兴趣、热情和商业敏感度\", \"具备高度诚信、投入度和自我驱动力\", \"顶尖院校本科或硕士学历，专业不限\", \"具备优秀的问题解决能力\", \"具备扎实的批判性思维能力\", \"中英文流利\"], \"bonus_points\": [\"有顶尖咨询公司或投资银行实习经历者优先\"], \"nice_to_have\": [\"具备互联网行业研究、经济研究、投资分析、商业分析相关理解或实践经验\", \"具备交易评估、尽职调查、投后研究或知识库建设相关理解\"]}, \"organizations\": [{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10010,'投资分析(技术方向)','企业发展事业群','北京','投资分析','技术投资分析','市场','应届实习','实习生','应届实习','这是一个连接投资决策与市场动态的关键角色。在这里，你将运用自己的洞察力和判断力，提供客观且精准的投资建议。','负责科技领域为主的行业及经济研究，参与项目搜寻、评估、尽职调查、交易执行、投后标的公司研究及团队知识库体系建设。','负责科技领域为主的行业及经济研究，参与项目搜寻、评估、尽职调查、交易执行、投后标的公司研究及团队知识库体系建设。','【必备要求】\n对科技投资领域及腾讯业务具有浓厚兴趣、热情及商业洞察力\n理工科专业背景，包括但不限于计算机科学与技术、电子信息工程、数学与统计学、数据科学与大数据技术、微电子学与集成电路、电子科学与技术、材料科学与工程、物理学等技术类专业\n具备高度诚信、敬业精神与自我驱动力\n具备出色的解决问题能力\n具备扎实的批判性思维\n中英文流利\n\n【了解项】\n具备科技行业研究、经济研究、投资分析、商业分析相关理解或实践经验\n具备项目搜寻、项目评估、尽职调查、交易执行或投后研究相关理解\n具备技术背景与商业分析结合能力','[\"主导以科技领域为主的行业及经济研究工作\", \"参与并助力项目搜寻、评估、尽职调查及交易执行全流程\", \"参与并助力交易完成后的标的公司研究工作\", \"完善并维护团队的知识库体系\"]','[\"对科技投资领域及腾讯业务具有浓厚兴趣、热情及商业洞察力\", \"理工科专业背景，包括但不限于计算机科学与技术、电子信息工程、数学与统计学、数据科学与大数据技术、微电子学与集成电路、电子科学与技术、材料科学与工程、物理学等技术类专业\", \"具备高度诚信、敬业精神与自我驱动力\", \"具备出色的解决问题能力\", \"具备扎实的批判性思维\", \"中英文流利\"]','[\"具备科技行业研究、经济研究、投资分析、商业分析相关理解或实践经验\", \"具备项目搜寻、项目评估、尽职调查、交易执行或投后研究相关理解\", \"具备技术背景与商业分析结合能力\"]','[]','[\"本岗位需上传 PDF 格式简历\"]','[\"投资分析\", \"技术投资\", \"科技行业研究\", \"经济研究\", \"商业分析\", \"项目搜寻\", \"项目评估\", \"尽职调查\", \"交易执行\", \"投后研究\", \"知识库建设\", \"计算机科学与技术\", \"电子信息工程\", \"数学与统计学\", \"数据科学与大数据技术\", \"微电子学与集成电路\", \"电子科学与技术\", \"材料科学与工程\", \"物理学\", \"商业洞察力\", \"问题解决\", \"批判性思维\", \"中文沟通\", \"英文沟通\"]','[\"投资分析\", \"技术投资\", \"科技行业研究\", \"经济研究\", \"商业分析\", \"项目搜寻\", \"项目评估\", \"尽职调查\", \"交易执行\", \"投后研究\", \"知识库建设\", \"计算机科学与技术\", \"电子信息工程\", \"数学与统计学\", \"数据科学与大数据技术\", \"微电子学与集成电路\", \"电子科学与技术\", \"材料科学与工程\", \"物理学\", \"商业洞察力\", \"问题解决\", \"批判性思维\", \"中文沟通\", \"英文沟通\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}]','[\"北京\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-investment-analysis-tech-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-investment-analysis-tech-intern-2026-001\", \"title\": \"投资分析(技术方向)\", \"slogan\": \"这是一个连接投资决策与市场动态的关键角色。在这里，你将运用自己的洞察力和判断力，提供客观且精准的投资建议。\", \"status\": \"open\", \"category\": \"技术投资分析\", \"job_type\": \"市场\", \"direction\": \"投资分析\", \"application_type\": \"应届实习\"}, \"facets\": {\"cities\": [\"北京\"], \"job_type\": \"市场\", \"direction\": \"投资分析\", \"job_category\": \"技术投资分析\", \"business_groups\": [\"CDG\"], \"application_project\": \"实习生\", \"application_subtype\": \"应届实习\"}, \"skills\": [\"投资分析\", \"技术投资\", \"科技行业研究\", \"经济研究\", \"商业分析\", \"项目搜寻\", \"项目评估\", \"尽职调查\", \"交易执行\", \"投后研究\", \"知识库建设\", \"计算机科学与技术\", \"电子信息工程\", \"数学与统计学\", \"数据科学与大数据技术\", \"微电子学与集成电路\", \"电子科学与技术\", \"材料科学与工程\", \"物理学\", \"商业洞察力\", \"问题解决\", \"批判性思维\", \"中文沟通\", \"英文沟通\"], \"source\": {\"source_url\": \"\", \"source_name\": \"tencent_campus_manual\", \"source_type\": \"manual_curated\", \"collected_at\": \"2026-06-01\", \"data_quality\": \"manual_verified\"}, \"locations\": [\"北京\"], \"description\": {\"summary\": \"负责科技领域为主的行业及经济研究，参与项目搜寻、评估、尽职调查、交易执行、投后标的公司研究及团队知识库体系建设。\", \"responsibilities\": [\"主导以科技领域为主的行业及经济研究工作\", \"参与并助力项目搜寻、评估、尽职调查及交易执行全流程\", \"参与并助力交易完成后的标的公司研究工作\", \"完善并维护团队的知识库体系\"]}, \"requirements\": {\"notes\": [\"本岗位需上传 PDF 格式简历\"], \"must_have\": [\"对科技投资领域及腾讯业务具有浓厚兴趣、热情及商业洞察力\", \"理工科专业背景，包括但不限于计算机科学与技术、电子信息工程、数学与统计学、数据科学与大数据技术、微电子学与集成电路、电子科学与技术、材料科学与工程、物理学等技术类专业\", \"具备高度诚信、敬业精神与自我驱动力\", \"具备出色的解决问题能力\", \"具备扎实的批判性思维\", \"中英文流利\"], \"bonus_points\": [], \"nice_to_have\": [\"具备科技行业研究、经济研究、投资分析、商业分析相关理解或实践经验\", \"具备项目搜寻、项目评估、尽职调查、交易执行或投后研究相关理解\", \"具备技术背景与商业分析结合能力\"]}, \"organizations\": [{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}], \"interview_locations\": [\"远程面试\"]}','manual_verified',NULL,0,NULL,'2026-06-07 12:09:49','2026-06-07 12:09:49'),(10011,'秘书','企业发展事业群','深圳总部','秘书','秘书','职能','应届实习','实习生','应届实习','你是部门里的重要担当，你眼观六路，大事小事，都放心上。你耳听八方，一切细节，尽在把握。你聚合团队，温暖人心。有你，更有爱！','负责部门管理者日程、会议、差旅等支持工作，承担部门职能事务统筹、流程制度协助、文化建设、信息传达及体系级活动组织支持。','负责部门管理者日程、会议、差旅等支持工作，承担部门职能事务统筹、流程制度协助、文化建设、信息传达及体系级活动组织支持。','【必备要求】\n本科及以上学历\n热情开朗，为人正直\n具备高效执行力，抗压性强\n具备良好的时间管理、情绪管理及沟通能力\n具备优秀的服务意识、高度责任感及团队合作精神\n能够与同事保持良好的工作关系\n工作例行化程度高，做事清晰有条理\n具有全局观及项目预见性、前瞻意识\n熟练运用各种日常办公软件及办公设备\n能独立组织大型团队活动并有创新意识\n\n【了解项】\n具备行政、人事、采购、资产、费用、合同、文档、资料管理等职能事务理解或实践经验\n具备部门文化建设、活动组织、流程优化、团队融合相关经验\n具备大型团队活动独立组织能力\n\n【加分项】\n有大型公司文秘实习经验\n英语能力突出','[\"负责部门管理者的日程管理、会议支持、差旅支持等工作，并协助管理者做好部门管理及团队融合\", \"担任部门内各项职能类工作接口人，包括行政、人事、采购、资产、费用、合同、文档、资料管理等，统筹管理相关事务\", \"根据部门管理要求，协助制定并实施部门级管理规章制度及各项流程，并定期优化\", \"负责部门文化建设，结合组织需求，通过活动组织、氛围建设、荣誉激励等方式建立良好的组织氛围，提升组织活力\", \"及时传达公司下发的各类管理规定及要求，保障管理要求在部门落地\", \"参与体系级活动组织，协助体系组织建设及文化落地\"]','[\"本科及以上学历\", \"热情开朗，为人正直\", \"具备高效执行力，抗压性强\", \"具备良好的时间管理、情绪管理及沟通能力\", \"具备优秀的服务意识、高度责任感及团队合作精神\", \"能够与同事保持良好的工作关系\", \"工作例行化程度高，做事清晰有条理\", \"具有全局观及项目预见性、前瞻意识\", \"熟练运用各种日常办公软件及办公设备\", \"能独立组织大型团队活动并有创新意识\"]','[\"具备行政、人事、采购、资产、费用、合同、文档、资料管理等职能事务理解或实践经验\", \"具备部门文化建设、活动组织、流程优化、团队融合相关经验\", \"具备大型团队活动独立组织能力\"]','[\"有大型公司文秘实习经验\", \"英语能力突出\"]','null','[\"秘书\", \"行政支持\", \"日程管理\", \"会议支持\", \"差旅支持\", \"部门管理支持\", \"团队融合\", \"行政事务\", \"人事事务\", \"采购事务\", \"资产管理\", \"费用管理\", \"合同管理\", \"文档管理\", \"资料管理\", \"流程制度建设\", \"流程优化\", \"部门文化建设\", \"活动组织\", \"氛围建设\", \"荣誉激励\", \"组织建设\", \"服务意识\", \"责任感\", \"时间管理\", \"情绪管理\", \"沟通表达\", \"团队合作\", \"办公软件\", \"办公设备\", \"英语能力\"]','[\"秘书\", \"行政支持\", \"日程管理\", \"会议支持\", \"差旅支持\", \"部门管理支持\", \"团队融合\", \"行政事务\", \"人事事务\", \"采购事务\", \"资产管理\", \"费用管理\", \"合同管理\", \"文档管理\", \"资料管理\", \"流程制度建设\", \"流程优化\", \"部门文化建设\", \"活动组织\", \"氛围建设\", \"荣誉激励\", \"组织建设\", \"服务意识\", \"责任感\", \"时间管理\", \"情绪管理\", \"沟通表达\", \"团队合作\", \"办公软件\", \"办公设备\", \"英语能力\"]','[{\"code\": \"CDG\", \"name\": \"企业发展事业群\"}, {\"code\": \"CSIG\", \"name\": \"云与智慧产业事业群\"}, {\"code\": \"IEG\", \"name\": \"互动娱乐事业群\"}, {\"code\": \"PCG\", \"name\": \"平台与内容事业群\"}, {\"code\": \"TEG\", \"name\": \"技术工程事业群\"}, {\"code\": \"WXG\", \"name\": \"微信事业群\"}, {\"code\": \"S1\", \"name\": \"职能系统－职能线\"}]','[\"深圳总部\", \"北京\", \"广州\", \"成都\"]','[\"远程面试\"]',NULL,'open','manual_curated','tencent-secretary-intern-2026-001',NULL,'','tencent_campus_manual','{\"job\": {\"id\": \"tencent-secretary-intern-2026-001\", \"title\": \"秘书\", \"slogan\": \"你是部门里的重要担当，你眼观六路，大事小事，都